"""Test for Nested field with callable returning a class name string."""
import pytest

from marshmallow import Schema, ValidationError, fields


class _CallableNestedStrSchema(Schema):
    name = fields.String()


def test_nested_callable_returning_string():
    """Test that Nested accepts a callable returning a string class name."""

    class MySchema(Schema):
        nested = fields.Nested(lambda: "_CallableNestedStrSchema")

    schema = MySchema()
    result = schema.load({"nested": {"name": "foo"}})
    assert result == {"nested": {"name": "foo"}}

    result = schema.dump({"nested": {"name": "foo"}})
    assert result == {"nested": {"name": "foo"}}


def test_nested_callable_returning_string_invalid_data():
    """Test validation works with callable returning string class name."""

    class MySchema(Schema):
        nested = fields.Nested(lambda: "_CallableNestedStrSchema")

    schema = MySchema()
    with pytest.raises(ValidationError):
        schema.load({"nested": {"invalid": "data"}})

